-- =====================================================================
-- VoucherFlow — update 2: donor account suggestions
-- Paste this whole file into Supabase → SQL Editor → new snippet → Run.
-- Run it once. (Running it again is harmless.)
-- =====================================================================

-- Known voucher number → donor account, per company.
create table if not exists public.account_history (
  id             bigint generated always as identity primary key,
  company_id     uuid not null references public.companies,
  voucher_no     bigint not null,
  donor_account  text not null,
  source         text not null default 'validated',   -- 'import' or 'validated'
  updated_at     timestamptz not null default now(),
  unique (company_id, voucher_no)
);

alter table public.account_history enable row level security;

drop policy if exists "read account history" on public.account_history;
create policy "read account history" on public.account_history for select to authenticated
  using (public.my_role() is not null);
drop policy if exists "admin manages account history" on public.account_history;
create policy "admin manages account history" on public.account_history for all to authenticated
  using (public.my_role() = 'admin') with check (public.my_role() = 'admin');

-- Every voucher saved with an account teaches the system (latest entry wins).
create or replace function public.learn_account()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if new.company_id is not null
     and new.donor_account is not null and btrim(new.donor_account) <> ''
     and new.voucher_number ~ '^\d{1,18}$'
     and new.status not in ('pending', 'cancelled')
     and new.deleted_at is null then
    insert into public.account_history (company_id, voucher_no, donor_account, source, updated_at)
    values (new.company_id, new.voucher_number::bigint, btrim(new.donor_account), 'validated', now())
    on conflict (company_id, voucher_no)
    do update set donor_account = excluded.donor_account, source = 'validated', updated_at = now();
  end if;
  return new;
end $$;

drop trigger if exists vouchers_learn_account on public.vouchers;
create trigger vouchers_learn_account
  after insert or update on public.vouchers
  for each row execute function public.learn_account();

-- Suggests the account of the nearest known voucher (within ±p_range numbers).
-- Gives no suggestion if the nearest vouchers disagree.
create or replace function public.suggest_account(p_company uuid, p_voucher text, p_range int default 10)
returns table (donor_account text, from_voucher bigint, distance bigint)
language sql stable set search_path = public as $$
  with target as (
    select case when p_voucher ~ '^\d{1,18}$' then p_voucher::bigint end as n
  ),
  near as (
    select h.donor_account, h.voucher_no, abs(h.voucher_no - t.n) as d
    from public.account_history h, target t
    where t.n is not null
      and h.company_id = p_company
      and h.voucher_no between t.n - p_range and t.n + p_range
  ),
  best as (select min(d) as d from near)
  select n.donor_account, n.voucher_no, n.d
  from near n, best b
  where n.d = b.d
    and (select count(distinct n2.donor_account) from near n2 where n2.d = b.d) = 1
  limit 1
$$;

grant execute on function public.suggest_account(uuid, text, int) to authenticated;

-- AAC: barcode rule, plus account history from the 1,584-row sheet.
do $$
declare
  cid uuid;
  rule text := 'AC[SN]\d{9}0*(?<voucher>[1-9]\d*)(?<amount>\d{5})';
begin
  select id into cid from public.companies
   where name ilike '%achisomoch%' or name ilike 'AAC%' or name ilike '% AAC%'
   order by created_at limit 1;
  if cid is null then
    insert into public.companies (name, submission_method, barcode_pattern, amount_divisor)
    values ('AAC – Achisomoch Aid Company', 'physical', rule, 100)
    returning id into cid;
  else
    update public.companies set barcode_pattern = rule, amount_divisor = 100 where id = cid;
  end if;

  insert into public.account_history (company_id, voucher_no, donor_account, source)
  select cid, v.n, v.a, 'import'
